-- Translation: sofia-goggia-profile -> nl
UPDATE articles
SET
    title = jsonb_set(COALESCE(title, '{}'::jsonb), '{nl}', '"Sofia Goggia: Italië''s onbevreesde afdalingskoningin"'::jsonb),
    excerpt = jsonb_set(COALESCE(excerpt, '{}'::jsonb), '{nl}', '"Sofia Goggia valt afdalingspistes aan met ongeëvenaarde agressie en moed. De Italiaanse kampioene heeft meerdere Wereldbeker-afdalingstitels gewonnen door onbevreesd te racen."'::jsonb),
    content = jsonb_set(COALESCE(content, '{}'::jsonb), '{nl}', '"<article><h2>De onbevreesde concurrent</h2><p>Sofia Goggia belichaamt de geest van afdalingsskiën: snelheid, moed en berekend risico. Geboren op 15 november 1992 in Bergamo, Italië, is ze door agressieve tactieken en mentale kracht de bepalende afdalingsracer van haar generatie geworden.</p><h2>Dominantie in de afdaling</h2><p>Goggia''s benadering van <a href=\"/nl/alpine-skiing-disciplines/\">afdalingsskiën</a> is uniek. Waar anderen hun lijn beschermen, valt zij aan. Haar bereidheid om grenzen te verleggen heeft opmerkelijke overwinningen en af en toe crashes opgeleverd. Als alles klopt, is ze onverslaanbaar.</p><h3>Racekenmerken</h3><ul><li><strong>Agressie</strong>: Valt aan van start tot finish</li><li><strong>Tuck-positie</strong>: Extreem aerodynamisch bij hoge snelheid</li><li><strong>Moed</strong>: Neemt risico''s die anderen vermijden</li><li><strong>Mentaal herstel</strong>: Herstelt snel van tegenslagen</li></ul><h2>Comeback-kampioene</h2><p>Goggia heeft meerdere ernstige blessures overwonnen. Elke keer komt ze sterker en vastberadener terug. Haar veerkracht is legendarisch geworden in de skiwereld.</p><h2>Italiaanse ski-trots</h2><p>Racen voor Italië op locaties als <a href=\"/nl/cortina-venue-guide/\">Cortina d''Ampezzo</a> en <a href=\"/nl/bormio-venue-guide/\">Bormio</a> heeft een speciale betekenis. Het thuispubliek inspireert haar tot nog grotere prestaties.</p><h2>Competitie</h2><p>Goggia''s belangrijkste rivalen zijn <a href=\"/nl/athletes/lara-gut-behrami-profile/\">Lara Gut-Behrami</a>, <a href=\"/nl/athletes/federica-brignone-profile/\">Federica Brignone</a> en <a href=\"/nl/athletes/cornelia-huetter-profile/\">Cornelia Hütter</a> uit Oostenrijk.</p><h2>Nalatenschap</h2><p>Goggia vertegenwoordigt alles wat opwindend is aan afdalingsskiën. Haar onbevreesde aanpak en emotionele racestijl hebben haar wereldwijd tot publiekslieveling gemaakt.</p></article>"'::jsonb),
    updated_at = NOW()
WHERE slug = 'sofia-goggia-profile';


-- Translation: sofia-goggia-profile -> ar
UPDATE articles
SET
    title = jsonb_set(COALESCE(title, '{}'::jsonb), '{ar}', '"صوفيا غوجا: ملكة إيطاليا الشجاعة في سباق الانحدار"'::jsonb),
    excerpt = jsonb_set(COALESCE(excerpt, '{}'::jsonb), '{ar}', '"صوفيا غوجا تهاجم مسارات الانحدار بعدوانية وشجاعة لا مثيل لهما. البطلة الإيطالية فازت بعدة ألقاب في كأس العالم للانحدار من خلال السباق الشجاع."'::jsonb),
    content = jsonb_set(COALESCE(content, '{}'::jsonb), '{ar}', '"<article><h2>المنافسة الشجاعة</h2><p>صوفيا غوجا تجسد روح التزلج على المنحدرات: السرعة والشجاعة والمخاطرة المحسوبة. ولدت في 15 نوفمبر 1992 في بيرغامو، إيطاليا، وأصبحت متزلجة الانحدار المميزة لجيلها من خلال التكتيكات العدوانية والقوة الذهنية.</p><h2>هيمنة الانحدار</h2><p>نهج غوجا في <a href=\"/ar/alpine-skiing-disciplines/\">تزلج الانحدار</a> فريد من نوعه. حيث يحمي الآخرون خطهم، هي تهاجم. استعدادها لتجاوز الحدود أنتج انتصارات رائعة وسقطات عرضية. عندما يعمل كل شيء، لا يمكن هزيمتها.</p><h3>خصائص السباق</h3><ul><li><strong>العدوانية</strong>: تهاجم من البداية إلى النهاية</li><li><strong>وضعية الانحناء</strong>: ديناميكية هوائية للغاية عند السرعة العالية</li><li><strong>الشجاعة</strong>: تأخذ مخاطر يتجنبها الآخرون</li><li><strong>التعافي الذهني</strong>: تتعافى بسرعة من الانتكاسات</li></ul><h2>بطلة العودة</h2><p>تغلبت غوجا على إصابات خطيرة متعددة. في كل مرة تعود أقوى وأكثر تصميماً. أصبحت مرونتها أسطورية في عالم سباقات التزلج.</p><h2>فخر التزلج الإيطالي</h2><p>السباق من أجل إيطاليا في أماكن مثل <a href=\"/ar/cortina-venue-guide/\">كورتينا دامبيتسو</a> و<a href=\"/ar/bormio-venue-guide/\">بورميو</a> يحمل معنى خاصاً. الجماهير المحلية تلهمها لأداء أعظم.</p><h2>المنافسة</h2><p>منافسات غوجا الرئيسيات هن <a href=\"/ar/athletes/lara-gut-behrami-profile/\">لارا غوت بيهرامي</a> و<a href=\"/ar/athletes/federica-brignone-profile/\">فيديريكا برينيوني</a> و<a href=\"/ar/athletes/cornelia-huetter-profile/\">كورنيليا هوتر</a> من النمسا.</p><h2>الإرث</h2><p>غوجا تمثل كل ما هو مثير في تزلج الانحدار. نهجها الشجاع وأسلوبها العاطفي في السباق جعلاها محبوبة الجماهير في جميع أنحاء العالم.</p></article>"'::jsonb),
    updated_at = NOW()
WHERE slug = 'sofia-goggia-profile';


-- Translation: sofia-goggia-profile -> ja
UPDATE articles
SET
    title = jsonb_set(COALESCE(title, '{}'::jsonb), '{ja}', '"ソフィア・ゴッジア：イタリアの恐れ知らずのダウンヒル女王"'::jsonb),
    excerpt = jsonb_set(COALESCE(excerpt, '{}'::jsonb), '{ja}', '"ソフィア・ゴッジアは比類なき攻撃性と勇気でダウンヒルコースに挑みます。このイタリアのチャンピオンは、恐れ知らずのレースで複数のワールドカップダウンヒルタイトルを獲得しています。"'::jsonb),
    content = jsonb_set(COALESCE(content, '{}'::jsonb), '{ja}', '"<article><h2>恐れ知らずの競技者</h2><p>ソフィア・ゴッジアはダウンヒルスキーの精神を体現しています：スピード、勇気、計算されたリスク。1992年11月15日、イタリアのベルガモ生まれで、攻撃的な戦術とメンタルの強さにより、彼女は世代を代表するダウンヒルレーサーになりました。</p><h2>ダウンヒルでの支配</h2><p>ゴッジアの<a href=\"/ja/alpine-skiing-disciplines/\">ダウンヒルスキー</a>へのアプローチはユニークです。他の選手がラインを守るところで、彼女は攻撃します。限界を押し広げる彼女の意欲は、驚くべき勝利と時折のクラッシュをもたらしました。すべてがうまくいくとき、彼女は無敵です。</p><h3>レースの特徴</h3><ul><li><strong>攻撃性</strong>：スタートからフィニッシュまで攻撃する</li><li><strong>タック姿勢</strong>：高速で極めて空力的</li><li><strong>勇気</strong>：他の人が避けるリスクを取る</li><li><strong>精神的回復力</strong>：挫折から素早く立ち直る</li></ul><h2>カムバックチャンピオン</h2><p>ゴッジアは複数の重傷を乗り越えてきました。毎回、より強く、より決意を持って戻ってきます。彼女の回復力はスキーレース界で伝説となっています。</p><h2>イタリアンスキーの誇り</h2><p><a href=\"/ja/cortina-venue-guide/\">コルティナ・ダンペッツォ</a>や<a href=\"/ja/bormio-venue-guide/\">ボルミオ</a>のような会場でイタリア代表としてレースすることは特別な意味があります。地元の観衆が彼女をさらに素晴らしいパフォーマンスへと鼓舞します。</p><h2>競争</h2><p>ゴッジアの主なライバルは、<a href=\"/ja/athletes/lara-gut-behrami-profile/\">ララ・グート・ベーラミ</a>、<a href=\"/ja/athletes/federica-brignone-profile/\">フェデリカ・ブリニョーネ</a>、そしてオーストリアの<a href=\"/ja/athletes/cornelia-huetter-profile/\">コルネリア・ヒュッター</a>です。</p><h2>レガシー</h2><p>ゴッジアはダウンヒルスキーのすべてのエキサイティングな要素を代表しています。彼女の恐れ知らずのアプローチと感情的なレーススタイルは、世界中でファンのお気に入りにしました。</p></article>"'::jsonb),
    updated_at = NOW()
WHERE slug = 'sofia-goggia-profile';


-- Translation: sofia-goggia-profile -> zh
UPDATE articles
SET
    title = jsonb_set(COALESCE(title, '{}'::jsonb), '{zh}', '"索菲亚·戈吉亚：意大利无畏的速降女王"'::jsonb),
    excerpt = jsonb_set(COALESCE(excerpt, '{}'::jsonb), '{zh}', '"索菲亚·戈吉亚以无与伦比的进攻性和勇气冲击速降赛道。这位意大利冠军通过无畏的比赛赢得了多个世界杯速降冠军。"'::jsonb),
    content = jsonb_set(COALESCE(content, '{}'::jsonb), '{zh}', '"<article><h2>无畏的竞争者</h2><p>索菲亚·戈吉亚体现了速降滑雪的精神：速度、勇气和计算的风险。1992年11月15日出生于意大利贝加莫，她通过激进的战术和强大的心理素质成为了这一代标志性的速降滑雪运动员。</p><h2>速降统治</h2><p>戈吉亚对<a href=\"/zh/alpine-skiing-disciplines/\">速降滑雪</a>的方式独一无二。当其他人保护自己的路线时，她进攻。她挑战极限的意愿带来了非凡的胜利和偶尔的摔倒。当一切顺利时，她是不可战胜的。</p><h3>比赛特点</h3><ul><li><strong>进攻性</strong>：从起点到终点全程进攻</li><li><strong>蛋形姿势</strong>：高速时极其符合空气动力学</li><li><strong>勇气</strong>：承担他人回避的风险</li><li><strong>心理恢复</strong>：从挫折中快速恢复</li></ul><h2>复出冠军</h2><p>戈吉亚克服了多次严重伤病。每次她都变得更强大、更坚定地回归。她的韧性在滑雪比赛界已成为传奇。</p><h2>意大利滑雪的骄傲</h2><p>在<a href=\"/zh/cortina-venue-guide/\">科尔蒂纳丹佩佐</a>和<a href=\"/zh/bormio-venue-guide/\">博尔米奥</a>等场地为意大利比赛具有特殊意义。主场观众激励她取得更好的成绩。</p><h2>竞争</h2><p>戈吉亚的主要对手是<a href=\"/zh/athletes/lara-gut-behrami-profile/\">拉拉·古特-贝拉米</a>、<a href=\"/zh/athletes/federica-brignone-profile/\">费德里卡·布里尼奥内</a>和奥地利的<a href=\"/zh/athletes/cornelia-huetter-profile/\">科内莉亚·许特尔</a>。</p><h2>传承</h2><p>戈吉亚代表了速降滑雪中所有令人兴奋的元素。她无畏的态度和充满激情的比赛风格使她成为全世界粉丝的最爱。</p></article>"'::jsonb),
    updated_at = NOW()
WHERE slug = 'sofia-goggia-profile';


-- Translation: sofia-goggia-profile -> ko
UPDATE articles
SET
    title = jsonb_set(COALESCE(title, '{}'::jsonb), '{ko}', '"소피아 고지아: 이탈리아의 두려움 없는 활강 여왕"'::jsonb),
    excerpt = jsonb_set(COALESCE(excerpt, '{}'::jsonb), '{ko}', '"소피아 고지아는 비할 데 없는 공격성과 용기로 활강 코스를 공략합니다. 이탈리아 챔피언은 두려움 없는 레이싱으로 여러 월드컵 활강 타이틀을 획득했습니다."'::jsonb),
    content = jsonb_set(COALESCE(content, '{}'::jsonb), '{ko}', '"<article><h2>두려움 없는 경쟁자</h2><p>소피아 고지아는 활강 스키의 정신을 구현합니다: 속도, 용기, 계산된 위험. 1992년 11월 15일 이탈리아 베르가모에서 태어나, 공격적인 전술과 정신적 강인함을 통해 그녀는 세대를 정의하는 활강 레이서가 되었습니다.</p><h2>활강 지배</h2><p>고지아의 <a href=\"/ko/alpine-skiing-disciplines/\">활강 스키</a> 접근 방식은 독특합니다. 다른 사람들이 라인을 보호할 때 그녀는 공격합니다. 한계를 밀어붙이려는 그녀의 의지는 놀라운 승리와 가끔의 충돌을 가져왔습니다. 모든 것이 맞아떨어질 때 그녀는 무적입니다.</p><h3>레이싱 특성</h3><ul><li><strong>공격성</strong>: 시작부터 끝까지 공격</li><li><strong>턱 자세</strong>: 고속에서 매우 공기역학적</li><li><strong>용기</strong>: 다른 사람들이 피하는 위험을 감수</li><li><strong>정신적 회복</strong>: 좌절에서 빠르게 회복</li></ul><h2>컴백 챔피언</h2><p>고지아는 여러 심각한 부상을 극복했습니다. 매번 더 강하고 결연하게 돌아옵니다. 그녀의 회복력은 스키 레이싱 세계에서 전설이 되었습니다.</p><h2>이탈리아 스키의 자부심</h2><p><a href=\"/ko/cortina-venue-guide/\">코르티나 담페초</a>와 <a href=\"/ko/bormio-venue-guide/\">보르미오</a> 같은 장소에서 이탈리아를 대표하여 경기하는 것은 특별한 의미가 있습니다. 홈 관중이 그녀에게 더 큰 성과를 위한 영감을 줍니다.</p><h2>경쟁</h2><p>고지아의 주요 라이벌은 <a href=\"/ko/athletes/lara-gut-behrami-profile/\">라라 구트-베라미</a>, <a href=\"/ko/athletes/federica-brignone-profile/\">페데리카 브리뇨네</a>, 그리고 오스트리아의 <a href=\"/ko/athletes/cornelia-huetter-profile/\">코르넬리아 휘터</a>입니다.</p><h2>유산</h2><p>고지아는 활강 스키의 모든 흥미로운 요소를 대표합니다. 그녀의 두려움 없는 접근 방식과 감정적인 레이싱 스타일은 전 세계적으로 팬들의 사랑을 받게 만들었습니다.</p></article>"'::jsonb),
    updated_at = NOW()
WHERE slug = 'sofia-goggia-profile';


COMMIT;

